package app.officinalibri;
import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.MessageDigest;import java.util.*;
/** Personal editorial metadata; never writes the manuscript or its images. */
public final class JourneyStore {
 private final MobileStore store;private static final long LIMIT=8L*1024*1024;
 public JourneyStore(MobileStore store){this.store=store;}
 public static void validate(File root,JSONObject project)throws Exception {File f=new File(root,"percorso.json");if(f.isFile()){if(f.length()>LIMIT)throw new IOException("Percorso oltre 8 MiB");check(MobileStore.json(f),project.getString("id"));}}
 private static void check(JSONObject j,String project)throws Exception {if(!"officina-percorso-1".equals(j.getString("format"))||!project.equals(j.getString("projectId"))||j.getInt("revision")<0)throw new IOException("Percorso non valido o di un altro libro");java.time.Instant.parse(j.getString("updatedAt"));JSONObject brief=j.getJSONObject("brief");for(String k:Arrays.asList("idea","readers","promise","outline","canon","style"))if(brief.getString(k).length()>200000)throw new IOException("Testo del percorso troppo lungo");for(String k:Arrays.asList("sources","findings","revisions","files","tasks","approvals","editions"))if(j.getJSONArray(k).length()>5000)throw new IOException("Troppi elementi nel percorso");}
 public static String digest(File root)throws Exception {File f=new File(root,"percorso.json");return JourneyContent.digest(root,f.isFile()?MobileStore.json(f):null);}
 public JSONObject load(String id)throws Exception {JSONObject p=store.read(id).getJSONObject("project");File root=store.folder(id),f=new File(root,"percorso.json");validate(root,p);JSONArray locations=new JSONArray();JSONArray pages=p.getJSONArray("pages");for(int i=0;i<pages.length();i++){JSONObject pg=pages.getJSONObject(i);locations.put(new JSONObject().put("id",pg.getString("id")).put("name",pg.getString("name")).put("includeEpub",pg.getBoolean("includeEpub")));}File nf=new File(root,"romanzo.json");if(nf.isFile()){JSONArray sections=MobileStore.json(nf).getJSONArray("sections");for(int i=0;i<sections.length();i++){JSONObject section=sections.getJSONObject(i);locations.put(new JSONObject().put("id",section.getString("id")).put("name","Capitolo: "+section.getString("title")).put("includeEpub",section.getBoolean("includeEpub")));}}return new JSONObject().put("journey",f.isFile()?MobileStore.json(f):JSONObject.NULL).put("digest",digest(root)).put("locations",locations).put("externalFiles",false);}
 public JSONObject save(String id,JSONObject value)throws Exception {JSONObject state=load(id),current=state.optJSONObject("journey");int revision=current==null?0:current.getInt("revision");String project=store.read(id).getJSONObject("project").getString("id");check(value,project);if(value.getInt("revision")!=revision)throw new IOException("Il percorso è cambiato: riaprilo prima di salvare");JSONObject next=new JSONObject(value.toString());prepareFindings(next,current,JourneyContent.digest(store.folder(id),next));next.put("revision",revision+1).put("updatedAt",java.time.Instant.now().toString());String data=next.toString();if(data.getBytes(StandardCharsets.UTF_8).length>LIMIT)throw new IOException("Percorso oltre 8 MiB");File root=store.folder(id),target=new File(root,"percorso.json");if(target.isFile())MobileStore.atomic(new File(root,"snapshots/percorso-"+revision+"-"+UUID.randomUUID()+".json"),new String(Files.readAllBytes(target.toPath()),StandardCharsets.UTF_8));MobileStore.atomic(target,data);return load(id);}
 public JSONObject approve(String id,JSONObject options)throws Exception {JSONObject state=load(id),j=state.optJSONObject("journey");if(j==null)throw new IOException("Salva prima il percorso");if(j.getInt("revision")!=options.getInt("revision"))throw new IOException("Il percorso è cambiato: riaprilo");if(!state.getString("digest").equals(options.getString("expectedDigest")))throw new IOException("Il libro è cambiato: aggiorna prima di approvare");String area=options.getString("area"),who=options.getString("by").trim(),notes=options.optString("notes","");if(!Arrays.asList("testo","illustrazioni","impaginazione","cartaceo","ebook").contains(area)||who.isEmpty()||who.length()>2000||notes.length()>200000)throw new IOException("Indica area e nome di chi approva");j.getJSONArray("approvals").put(new JSONObject().put("id",UUID.randomUUID().toString()).put("area",area).put("by",who).put("date",java.time.Instant.now().toString()).put("digest",state.getString("digest")).put("notes",notes));return save(id,j);}
 public JSONObject review(String id,JSONObject options)throws Exception {JSONObject state=load(id),j=state.optJSONObject("journey");if(j==null||j.getInt("revision")!=options.getInt("revision")||!state.getString("digest").equals(options.getString("expectedDigest")))throw new IOException("Il libro o il percorso è cambiato: aggiorna prima di registrare la revisione");String domain=options.getString("domain"),result=options.getString("result"),by=options.getString("by").trim();if(!Arrays.asList("tecnica","compositiva","narrativa","autoriale").contains(domain)||!Arrays.asList("approvata","modifiche richieste").contains(result)||by.isEmpty()||by.length()>2000||options.optString("notes").length()>200000)throw new IOException("Revisione non valida");if(!j.has("reviews"))j.put("reviews",new JSONArray());j.getJSONArray("reviews").put(new JSONObject().put("id",UUID.randomUUID().toString()).put("domain",domain).put("result",result).put("by",by).put("notes",options.optString("notes","")).put("digest",state.getString("digest")).put("date",java.time.Instant.now().toString()));return save(id,j);}
 private static void prepareFindings(JSONObject next,JSONObject current,String digest)throws Exception {JSONArray list=next.getJSONArray("findings");Map<String,JSONObject> prior=new HashMap<>();if(current!=null){JSONArray old=current.getJSONArray("findings");for(int i=0;i<old.length();i++)prior.put(old.getJSONObject(i).getString("id"),old.getJSONObject(i));}for(int i=0;i<list.length();i++){JSONObject f=list.getJSONObject(i),old=prior.get(f.getString("id"));JSONArray history=old==null?new JSONArray():old.optJSONArray("history");if(history==null)history=new JSONArray();boolean changed=old==null||!f.getString("status").equals(old.getString("status"))||!f.getString("resolution").equals(old.getString("resolution"))||!Objects.equals(f.opt("resolvedDigest"),old.opt("resolvedDigest"));Object resolved=old==null?JSONObject.NULL:old.opt("resolvedDigest");if(changed){boolean open="aperto".equals(f.getString("status"));if(!open&&f.getString("resolution").trim().isEmpty())throw new IOException("Indica una motivazione per chiudere o accettare il rilievo");resolved=open?JSONObject.NULL:digest;history.put(new JSONObject().put("status",f.getString("status")).put("resolution",f.getString("resolution")).put("digest",resolved).put("date",java.time.Instant.now().toString()));}f.put("resolvedDigest",resolved==null?JSONObject.NULL:resolved).put("history",history);}}
 public JSONArray history(String id)throws Exception {File[] files=new File(store.folder(id),"snapshots").listFiles((d,n)->n.matches("percorso-[0-9]+-[a-f0-9-]+\\.json"));JSONArray result=new JSONArray();if(files!=null){Arrays.sort(files,Comparator.comparingInt((File f)->Integer.parseInt(f.getName().split("-")[1])).reversed());for(File f:files)result.put(f.getName());}return result;}
 public JSONObject restore(String id,String name,int revision)throws Exception {if(!name.matches("percorso-[0-9]+-[a-f0-9-]+\\.json"))throw new IOException("Versione del percorso non riconosciuta");JSONObject current=load(id).optJSONObject("journey");if(current==null||current.getInt("revision")!=revision)throw new IOException("Il percorso è cambiato: riaprilo");JSONObject old=MobileStore.json(new File(store.folder(id),"snapshots/"+name));for(String k:Arrays.asList("findings","reviews","artifacts","editions","approvals","revisions")){LinkedHashMap<String,JSONObject> items=new LinkedHashMap<>();for(JSONObject source:Arrays.asList(old,current)){JSONArray array=source.optJSONArray(k);if(array!=null)for(int i=0;i<array.length();i++){JSONObject v=array.getJSONObject(i);items.put(v.getString("id"),v);}}JSONArray merged=new JSONArray();for(JSONObject v:items.values())merged.put(v);old.put(k,merged);}old.put("revision",revision);return save(id,old);}
}
